using DrawVerify.Core.Interfaces;
using DrawVerify.Core.Models;
using Microsoft.Data.Sqlite;

namespace DrawVerify.Infrastructure.Persistence;

public sealed class SqliteAuthenticationAuditRepository : IAuthenticationAuditRepository
{
    private readonly string _connectionString;
    private readonly ICentralizedLogger? _logger;
    public SqliteAuthenticationAuditRepository(string databasePath, ICentralizedLogger? logger = null)
    {
        _connectionString = new SqliteConnectionStringBuilder { DataSource = databasePath }.ToString(); _logger = logger;
        try { using var c = new SqliteConnection(_connectionString); c.Open(); EnsureSchema(c); } catch (Exception ex) { logger?.Log(ex, "SQLite authentication audit startup", "Unable to initialize authentication audit schema"); throw; }
    }
    public async Task WriteAsync(AuthenticationAuditEntry entry, CancellationToken cancellationToken = default) { await using var c = new SqliteConnection(_connectionString); await c.OpenAsync(cancellationToken); await using var q = c.CreateCommand(); q.CommandText = InsertSql; Add(q, entry); await q.ExecuteNonQueryAsync(cancellationToken); }
    internal static async Task InsertAsync(SqliteConnection c, SqliteTransaction tx, AuthenticationAuditEntry entry, CancellationToken token) { await using var q = c.CreateCommand(); q.Transaction = tx; q.CommandText = InsertSql; Add(q, entry); await q.ExecuteNonQueryAsync(token); }
    internal static void EnsureSchema(SqliteConnection c)
    {
        using var q = c.CreateCommand(); q.CommandText = "CREATE TABLE IF NOT EXISTS AuthenticationAuditLog (AuditId TEXT PRIMARY KEY, ActorUsername TEXT NULL, Username TEXT NOT NULL, TimestampUtc TEXT NOT NULL, Action TEXT NOT NULL, Result TEXT NOT NULL, FailureReason TEXT NULL, RolesBefore TEXT NULL, RolesAfter TEXT NULL, SourceIdentifier TEXT NULL, ChangedFields TEXT NULL, OldValues TEXT NULL, NewValues TEXT NULL, DeactivationReason TEXT NULL, FailedAttemptCount INTEGER NULL);"; q.ExecuteNonQuery();
        foreach (var (column, definition) in new[] { ("RolesBefore", "TEXT NULL"), ("RolesAfter", "TEXT NULL"), ("SourceIdentifier", "TEXT NULL"), ("ChangedFields", "TEXT NULL"), ("OldValues", "TEXT NULL"), ("NewValues", "TEXT NULL"), ("DeactivationReason", "TEXT NULL"), ("FailedAttemptCount", "INTEGER NULL") }) AddColumnIfMissing(c, column, definition);
        using var index = c.CreateCommand(); index.CommandText = "CREATE INDEX IF NOT EXISTS IX_AuthenticationAuditLog_Query ON AuthenticationAuditLog(TimestampUtc, Action, Username, ActorUsername);"; index.ExecuteNonQuery();
    }
    public async Task<AuditLogPage> QueryAsync(AuditLogQuery query, CancellationToken cancellationToken = default)
    {
        query.Validate(); await using var c = new SqliteConnection(_connectionString); await c.OpenAsync(cancellationToken); await using var count = c.CreateCommand(); count.CommandText = FilterSql("SELECT COUNT(*) FROM AuthenticationAuditLog WHERE "); AddFilters(count, query); var total = Convert.ToInt32(await count.ExecuteScalarAsync(cancellationToken)); await using var cmd = c.CreateCommand(); cmd.CommandText = FilterSql("SELECT ActorUsername,Username,TimestampUtc,Action,Result,FailureReason,RolesBefore,RolesAfter,SourceIdentifier,ChangedFields,OldValues,NewValues,DeactivationReason,FailedAttemptCount FROM AuthenticationAuditLog WHERE ") + " ORDER BY TimestampUtc, AuditId LIMIT $limit OFFSET $offset"; AddFilters(cmd, query); cmd.Parameters.AddWithValue("$limit", query.PageSize); cmd.Parameters.AddWithValue("$offset", (query.Page - 1) * query.PageSize); var entries = new List<AuthenticationAuditEntry>(); await using var r = await cmd.ExecuteReaderAsync(cancellationToken); while (await r.ReadAsync(cancellationToken)) entries.Add(Read(r)); return new AuditLogPage(entries, query.Page, query.PageSize, total);
    }
    private static string FilterSql(string prefix) => prefix + "($from IS NULL OR TimestampUtc >= $from) AND ($to IS NULL OR TimestampUtc <= $to) AND ($action IS NULL OR Action = $action OR (Action = 'Login' AND (($action = 'LoginSuccess' AND Result = 'Success') OR ($action = 'LoginFailure' AND Result = 'Failure')))) AND ($username IS NULL OR Username = $username) AND ($actor IS NULL OR ActorUsername = $actor)";
    private static void AddFilters(SqliteCommand q, AuditLogQuery x) { q.Parameters.AddWithValue("$from", x.FromUtc?.ToUniversalTime().ToString("O") ?? (object)DBNull.Value); q.Parameters.AddWithValue("$to", x.ToUtc?.ToUniversalTime().ToString("O") ?? (object)DBNull.Value); q.Parameters.AddWithValue("$action", (object?)x.Action ?? DBNull.Value); q.Parameters.AddWithValue("$username", (object?)x.Username ?? DBNull.Value); q.Parameters.AddWithValue("$actor", (object?)x.ActorUsername ?? DBNull.Value); }
    private static AuthenticationAuditEntry Read(SqliteDataReader r) => new(r.IsDBNull(0) ? null : r.GetString(0), r.GetString(1), DateTimeOffset.Parse(r.GetString(2)), r.GetString(3), r.GetString(4), S(r, 5), S(r, 6), S(r, 7), S(r, 8), S(r, 9), S(r, 10), S(r, 11), S(r, 12), r.IsDBNull(13) ? null : r.GetInt32(13));
    private static string? S(SqliteDataReader r, int i) => r.IsDBNull(i) ? null : r.GetString(i);
    private static void Add(SqliteCommand q, AuthenticationAuditEntry e) { q.Parameters.AddWithValue("$id", Guid.NewGuid().ToString()); q.Parameters.AddWithValue("$actor", (object?)e.ActorUsername ?? DBNull.Value); q.Parameters.AddWithValue("$u", e.Username); q.Parameters.AddWithValue("$t", e.TimestampUtc.ToUniversalTime().ToString("O")); q.Parameters.AddWithValue("$a", e.Action); q.Parameters.AddWithValue("$r", e.Result); q.Parameters.AddWithValue("$f", (object?)e.FailureReason ?? DBNull.Value); q.Parameters.AddWithValue("$before", (object?)e.RolesBefore ?? DBNull.Value); q.Parameters.AddWithValue("$after", (object?)e.RolesAfter ?? DBNull.Value); q.Parameters.AddWithValue("$source", (object?)e.SourceIdentifier ?? DBNull.Value); q.Parameters.AddWithValue("$fields", (object?)e.ChangedFields ?? DBNull.Value); q.Parameters.AddWithValue("$old", (object?)e.OldValues ?? DBNull.Value); q.Parameters.AddWithValue("$new", (object?)e.NewValues ?? DBNull.Value); q.Parameters.AddWithValue("$reason", (object?)e.DeactivationReason ?? DBNull.Value); q.Parameters.AddWithValue("$attempts", (object?)e.FailedAttemptCount ?? DBNull.Value); }
    private static void AddColumnIfMissing(SqliteConnection c, string column, string definition) { using var q = c.CreateCommand(); q.CommandText = $"ALTER TABLE AuthenticationAuditLog ADD COLUMN {column} {definition}"; try { q.ExecuteNonQuery(); } catch (SqliteException ex) when (ex.Message.Contains("duplicate column", StringComparison.OrdinalIgnoreCase)) { } }
    private const string InsertSql = "INSERT INTO AuthenticationAuditLog (AuditId,ActorUsername,Username,TimestampUtc,Action,Result,FailureReason,RolesBefore,RolesAfter,SourceIdentifier,ChangedFields,OldValues,NewValues,DeactivationReason,FailedAttemptCount) VALUES ($id,$actor,$u,$t,$a,$r,$f,$before,$after,$source,$fields,$old,$new,$reason,$attempts)";
}
